let siteSettings=null;
async function loadSiteSettings(){try{const r=await fetch('/api/settings');if(!r.ok)throw Error();siteSettings=await r.json();EheLogic.setPricing(siteSettings.pricing)}catch{siteSettings=null}}
function editableNodes(doc=document){const walker=doc.createTreeWalker(doc.querySelector('#main'),NodeFilter.SHOW_TEXT),nodes=[];while(walker.nextNode()){const n=walker.currentNode;if(n.textContent.trim()&&!n.parentElement.closest('script,style,#calculator,.rental-section,dialog,form,#events-calendar,#leader-profile'))nodes.push(n)}return nodes}
function applySiteContent(){
 if(siteSettings){for(const node of editableNodes()){const key=node.textContent;node.eheOriginal=key;if(Object.hasOwn(siteSettings.texts[lang],key))node.textContent=siteSettings.texts[lang][key]}
 document.querySelectorAll('#main img').forEach(img=>{const original=img.getAttribute('src');img.dataset.originalImage=original;if(siteSettings.images[original])img.src=siteSettings.images[original]});
 if(page===1){const prices=document.querySelectorAll('.service .small');if(prices[0])prices[0].textContent=t('Pool päeva ','Half day ')+money(siteSettings.pricing.packages.half)+' · '+t('Terve päev ','Full day ')+money(siteSettings.pricing.packages.full);if(prices[1])prices[1].textContent=t('Kuni 14 tundi koordineerimist · ','Up to 14 hours of coordination · ')+money(siteSettings.pricing.packages.coordination)}
 }
 if(page===3){const leader=siteSettings?.leader||{name:'Karen',et:'EHE Eventsi juht',en:'Head of EHE Events',image:''},section=document.createElement('section');section.id='leader-profile';section.className='section leader-profile';section.innerHTML=(leader.image?`<img src="${escapeText(leader.image)}" alt="${escapeText(leader.name)}">`:`<div class="portrait-placeholder" aria-label="${t('Juhi foto lisandub','Portrait coming soon')}">EHE</div>`)+`<div><span class="eyebrow">${t('EHE EVENTSI JUHT','HEAD OF EHE EVENTS')}</span><h2>${escapeText(leader.name)}</h2><p>${escapeText(leader[lang])}</p><a href="mailto:karen@eheevents.ee">karen@eheevents.ee</a></div>`;$('#main').append(section)}
 if(page===1)initEventCalendar();
}
async function initEventCalendar(){
 const section=document.createElement('section');section.id='events-calendar';section.className='section events-calendar';section.innerHTML=`<span class="eyebrow">${t('PLANEERIME TEIE PÄEVA','PLAN YOUR DAY')}</span><h2>${t('Ürituste kalender','Event availability')}</h2><p>${t('Vaata vabu päevi ja saada meile oma soov. Vaba päev ei ole veel broneering; kinnitame kuupäeva personaalselt.','Check available dates and send your wishes. An available day is not a reservation; we confirm your date personally.')}</p><div class="calendar-head"><button id="event-prev" aria-label="${t('Eelmine kuu','Previous month')}">‹</button><h3 id="event-month"></h3><button id="event-next" aria-label="${t('Järgmine kuu','Next month')}">›</button></div><div id="event-days" class="calendar-grid"></div><p id="event-calendar-status" role="status"></p>`;$('#main').append(section);
 let month=new Date(tallinnDate().slice(0,7)+'-01T12:00Z'),closures;
 const draw=()=>{const y=month.getUTCFullYear(),m=month.getUTCMonth(),today=tallinnDate();$('#event-month').textContent=new Intl.DateTimeFormat(locale(),{month:'long',year:'numeric',timeZone:'UTC'}).format(month);$('#event-prev').disabled=month.toISOString().slice(0,7)<=today.slice(0,7);let html=t('E,T,K,N,R,L,P','M,T,W,T,F,S,S').split(',').map(x=>'<span class="weekday">'+x+'</span>').join('')+'<span></span>'.repeat((month.getUTCDay()+6)%7);for(let d=1;d<=new Date(Date.UTC(y,m+1,0)).getUTCDate();d++){const date=`${y}-${String(m+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`,past=date<today,busy=closures?.some(c=>c.from<=date&&c.to>=date),available=closures&&!busy&&!past;html+=`<button ${available?'':'disabled'} class="calendar-day ${available?'available':'unavailable'}" data-event-date="${date}" aria-label="${date} ${past?t('Möödunud','Past'):!closures?t('Saadavus teadmata','Availability unknown'):busy?t('Hõivatud','Unavailable'):t('Vaba','Available')}">${d}</button>`}$('#event-days').innerHTML=html;document.querySelectorAll('[data-event-date]').forEach(b=>b.onclick=()=>location.href=url('/contact/')+'&date='+b.dataset.eventDate);};
 $('#event-prev').onclick=()=>{month.setUTCMonth(month.getUTCMonth()-1);draw()};$('#event-next').onclick=()=>{month.setUTCMonth(month.getUTCMonth()+1);draw()};draw();try{const r=await fetch('/api/events');if(!r.ok)throw Error();closures=await r.json();$('#event-calendar-status').textContent=t('Värviline päev: vaba · hall päev: hõivatud või möödunud.','Coloured date: available · grey date: unavailable or past.');draw()}catch{$('#event-calendar-status').textContent=t('Kalendrit ei saanud laadida. Palun küsi saadavust e-posti teel.','Unable to load the calendar. Please email us to check availability.')}
}
